QOS_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm", "lags",
     "mirror", "acl", "qos", "max_frame")
)
QOS_CHECK_FRAME_KEYS = frozenset(
    ("t", "port", "src", "dst", "vlan", "ethertype", "priority", "length",
     "fcs", "alignment")
)


def validate_qos_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm/lags/mirror/acl/qos 与 qos
    # 契约一致，复用其全量校验
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
    ) = validate_qos_config({key: config[key] for key in QOS_CONFIG_KEYS})
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror, acl,
        qos, max_frame,
    )


def validate_qos_check_events(events, ports, link_ids, lags):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            t = event["t"]
            lid = event["id"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            t = event["t"]
            member = event["member"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        elif keys == SERVICE_EVENT_KEYS:
            t = event["t"]
            port = event["port"]
            count = event["count"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
        elif keys == QOS_CHECK_FRAME_KEYS:
            t = event["t"]
            port = event["port"]
            src = event["src"]
            dst = event["dst"]
            vlan = event["vlan"]
            ethertype = event["ethertype"]
            priority = event["priority"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if not valid_dst_mac(dst):
                raise InvalidInput("bad dst")
            if vlan is not None and not _valid_vlan_id(vlan):
                raise InvalidInput("bad vlan")
            if not _is_int(ethertype) or not 0 <= ethertype <= 65535:
                raise InvalidInput("bad ethertype")
            if not _is_int(priority) or not 0 <= priority <= 7:
                raise InvalidInput("bad priority")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                (
                    "frame", t, port, src, dst, vlan, ethertype, priority,
                    length, fcs, alignment,
                )
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


SECURITY_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm", "lags",
     "mirror", "acl", "qos", "security", "max_frame")
)


def validate_security_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != SECURITY_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age/storm/lags/mirror/acl/qos/
    # security 与 port-security 契约一致，复用其全量校验
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
    ) = validate_security_config(
        {key: config[key] for key in SECURITY_CONFIG_KEYS}
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror, acl,
        qos, security, max_frame,
    )


def validate_security_check_events(events, ports, link_ids, lags):
    # 链路、成员、service 事件沿用 port-security；帧项为 port-security 帧项
    # 仅增 length/fcs/alignment，与 qos-check 同形，复用其全量校验
    return validate_qos_check_events(events, ports, link_ids, lags)


def _reload_port_identity_ok(current_ports, new_ports):
    """热加载端口身份不可变：名称与顺序、up 状态逐位置一致。

    仅 mode/pvid/allowed/untagged 允许热变更；端口增删、重排或 up 变化
    均拒绝。
    """
    if len(current_ports) != len(new_ports):
        return False
    for old, new in zip(current_ports, new_ports):
        if old["name"] != new["name"] or old["up"] != new["up"]:
            return False
    return True


def _reload_changes(current, new_config):
    """按 RELOAD_MUTABLE_KEYS 固定次序列出实际变化项。"""
    return [
        {
            "key": key,
            "before": _canonical(current[key]),
            "after": _canonical(new_config[key]),
        }
        for key in RELOAD_MUTABLE_KEYS
        if new_config[key] != current[key]
    ]


def validate_reload_events(events, ports, link_ids, lags, config,
                           allow_rollback=False):
    """reload 子命令事件：普通事件沿用 qos，另含 {t, config} 重载事件。

    返回 (事件序列, 末态原始配置)；重载事件的 config 须为完整有效配置，
    且仅 age/ports（限 mode/pvid/allowed/untagged）/storm/mirror/acl/qos/
    security 可与当时配置不同。全部校验先于执行。
    allow_rollback 时另含 {t, rollback} 事件（rollback 只能为 true）：
    reload 前压入当前配置，rollback 弹栈恢复，空栈为 invalid_input。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    member_set = {member for lag in lags for member in lag["members"]}
    result = []
    prev_t = None
    current = config
    stack = []  # reload 前压入的原始配置；rollback 弹栈恢复
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            t = event["t"]
            lid = event["id"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == MEMBER_EVENT_KEYS:
            t = event["t"]
            member = event["member"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(member, str) or member not in member_set:
                raise InvalidInput("bad event member")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("member", t, member, up))
        elif keys == SERVICE_EVENT_KEYS:
            t = event["t"]
            port = event["port"]
            count = event["count"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not _is_int(count) or count <= 0:
                raise InvalidInput("bad count")
            result.append(("service", t, port, count))
        elif keys == FRAME_KEYS_ACL:
            t = event["t"]
            port = event["port"]
            src = event["src"]
            dst = event["dst"]
            vlan = event["vlan"]
            ethertype = event["ethertype"]
            priority = event["priority"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if not valid_dst_mac(dst):
                raise InvalidInput("bad dst")
            if vlan is not None and not _valid_vlan_id(vlan):
                raise InvalidInput("bad vlan")
            if not _is_int(ethertype) or not 0 <= ethertype <= 65535:
                raise InvalidInput("bad ethertype")
            if not _is_int(priority) or not 0 <= priority <= 7:
                raise InvalidInput("bad priority")
            result.append(
                ("frame", t, port, src, dst, vlan, ethertype, priority)
            )
        elif keys == RELOAD_EVENT_KEYS:
            t = event["t"]
            new_config = event["config"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(new_config, dict):
                raise InvalidInput("bad reload config")
            (
                _bridges,
                _links,
                _delay,
                _bridge,
                new_ports,
                new_age,
                new_storm,
                _lags,
                new_mirror,
                new_acl,
                new_qos,
                new_security,
            ) = validate_security_config(new_config)
            for key in current:
                if (
                    key not in RELOAD_MUTABLE_KEYS
                    and new_config[key] != current[key]
                ):
                    raise InvalidInput(
                        "reload may only change "
                        "age/ports/storm/mirror/acl/qos/security"
                    )
            if not _reload_port_identity_ok(
                current["ports"], new_config["ports"]
            ):
                raise InvalidInput(
                    "reload may only change port "
                    "mode/pvid/allowed/untagged"
                )
            changes = _reload_changes(current, new_config)
            if allow_rollback:
                stack.append(current)  # reload 前压入当前配置
            current = new_config
            result.append(
                (
                    "reload",
                    t,
                    new_age,
                    new_ports,
                    new_storm,
                    new_mirror,
                    new_acl,
                    new_qos,
                    new_security,
                    changes,
                )
            )
        elif allow_rollback and keys == ROLLBACK_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if event["rollback"] is not True:
                raise InvalidInput("bad rollback")
            if not stack:
                raise InvalidInput("rollback stack empty")
            new_config = stack.pop()
            (
                _bridges,
                _links,
                _delay,
                _bridge,
                new_ports,
                new_age,
                new_storm,
                _lags,
                new_mirror,
                new_acl,
                new_qos,
                new_security,
            ) = validate_security_config(new_config)
            changes = _reload_changes(current, new_config)
            current = new_config
            result.append(
                (
                    "rollback",
                    t,
                    new_age,
                    new_ports,
                    new_storm,
                    new_mirror,
                    new_acl,
                    new_qos,
                    new_security,
                    changes,
                )
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result, current


def forward_lag(
    bridges, links, delay, bridge_name, ports, age, storm, lags, events
):
    """lag 公共入口：精确签名不变，无 observer 形参。

    record/replay 所需的逐事件观察逻辑封装在内部 _forward_lag_run 中。

def forward_lag(
    bridges, links, delay, bridge_name, ports, age, storm, lags, events
):
    """lag 公共入口：精确签名不变，无 observer 形参。

    record/replay 所需的逐事件观察逻辑封装在内部 _forward_lag_run 中。
    """
    return _forward_lag_run(
        bridges, links, delay, bridge_name, ports, age, storm, lags, events,
        observer=None,
    )


def _forward_lag_run(
    bridges, links, delay, bridge_name, ports, age, storm, lags, events,
    observer=None,
):
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    lag_by_name = {lag["name"]: lag for lag in lags}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    port_stats = {
        port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻
    results = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def lag_candidates(lag, t, vlan):
        """可用候选成员，按 members 顺序。"""
        return [
            member
            for member in lag["members"]
            if member_available(member, t, vlan)
        ]

    def lag_pick(lag, candidates, src, dst, vlan):
        parts = []
        for field in lag["hash"]:
            if field == "src":
                parts.append(src)
            elif field == "dst":
                parts.append(dst)
            else:
                parts.append(str(vlan))
        digest = zlib.crc32("|".join(parts).encode("utf-8")) & 0xFFFFFFFF
        return candidates[digest % len(candidates)]

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != learn_port:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [learn_port, t]
        last_learn[(vlan, src)] = learn_port
        return False

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if item[0] == "link":
            _, t, lid, up = item
            link_changed = by_id[lid]["up"] != up
            if link_changed:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[lid]["up"] = up
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
            if observer is not None:
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": link_changed,
                     "output": None}
                )
            continue
        if item[0] == "member":
            _, t, member, up = item
            member_changed = member_up[member] != up
            member_up[member] = up  # 幂等无作用；可用性变化不清 FDB
            if observer is not None:
                observer["items"].append(
                    {"kind": "member", "t": t, "applied": member_changed,
                     "output": None}
                )
            continue
        _, t, port_name, src, dst, tag = item
        port_stats[port_name]["rx"] += 1
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            entry = {"t": t, "action": "drop", "ports": []}
            results.append(entry)
            if observer is not None:  # 准入拒绝也逐帧记录
                observer["items"].append(
                    {"kind": "frame", "t": t, "applied": True,
                     "output": entry}
                )
            continue
        vlan_stats[vlan]["rx"] += 1
        ingress_lag = lag_of.get(port_name)
        if ingress_lag is not None:
            usable = member_available(port_name, t, vlan)
            state = "forwarding" if usable else None
        else:
            usable = True
            _, state = port_status(port_name, t)
        egress = []
        action = "drop"
        if usable:  # 不可用成员入帧丢弃且不学习
            learn_port = ingress_lag["name"] if ingress_lag else port_name
            suppressed = suppress(
                t, port_name, vlan, src, dst, state, learn_port
            )
            if not suppressed and state == "forwarding":
                is_group = int(dst[:2], 16) & 1
                hit = None if is_group else fdb.get((vlan, dst))
                if hit is not None and hit[0] != learn_port:
                    target = hit[0]
                    target_lag = lag_by_name.get(target)
                    if target_lag is not None:
                        candidates = lag_candidates(target_lag, t, vlan)
                        if candidates:  # 无候选按无出口丢弃
                            egress = [
                                lag_pick(target_lag, candidates, src, dst, vlan)
                            ]
                            action = "unicast"
                    else:
                        target_up, target_state = port_status(target, t)
                        if (
                            target_up
                            and target_state == "forwarding"
                            and vlan in by_name[target]["allowed"]
                        ):
                            egress = [target]
                            action = "unicast"
                elif hit is None:
                    selected = {}  # lag 名 -> 本帧选中的成员
                    for lag in lags:
                        if ingress_lag is not None and lag is ingress_lag:
                            continue  # 禁止组内回送
                        candidates = lag_candidates(lag, t, vlan)
                        if candidates:
                            selected[lag["name"]] = lag_pick(
                                lag, candidates, src, dst, vlan
                            )
                    for port in ports:
                        name = port["name"]
                        lag = lag_of.get(name)
                        if lag is not None:
                            if selected.get(lag["name"]) == name:
                                egress.append(name)
                        elif (
                            vlan in port["allowed"]
                            and name != port_name
                            and port_status(name, t) == (True, "forwarding")
                        ):
                            egress.append(name)
                    if egress:
                        action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        entry = {"t": t, "action": action, "ports": out_ports}
        results.append(entry)
        if observer is not None:  # 帧项恒 applied，output 为对应结果项
            observer["items"].append(
                {"kind": "frame", "t": t, "applied": True, "output": entry}
            )
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def lag_work(
    bridges, links, delay, bridge_name, ports, age, storm, lags, events, limit
):
    """lag 的工作量预演：独立链路副本与空状态，无副作用。

    B、L、P、M 为桥、链路、端口、成员数，U 为 up 链路数；初始收敛计
    B+L+2U。各事件在按 t 老化 FDB 与解封前取 K=FDB 项数、H=封锁项数、
    Q=速率与迁移队列时间戳总数：帧计 K+H+Q+P+M+1；链路先应用 up，改变
    计 K+H+Q+B+L+2U+2P+1，幂等计 K+H+Q+1；成员事件计 K+H+Q+1。再按
    既有规则处理并更新预演状态。累计等于上限合法，首次超过即抛
    LagWorkLimit。
    """
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    B = len(bridges)
    L = len(links)
    P = len(ports)
    sim_links = [dict(link) for link in links]
    by_id = {link["id"]: link for link in sim_links}
    by_name = {port["name"]: port for port in ports}
    lag_of = {}  # 成员物理口 -> lag
    member_up = {}  # 成员物理口 -> 动态可用（初始可用）
    for lag in lags:
        for member in lag["members"]:
            lag_of[member] = lag
            member_up[member] = True
    M = len(member_up)
    port_link = {}  # 本桥桥链路口名 -> link
    for link in sim_links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [逻辑口（物理口名或 lag 名）, seen]
    rate_queues = {}  # (入端口, vlan, 类别) -> 放行时刻 deque
    move_queues = {}  # (vlan, src) -> 迁移时刻 deque
    last_learn = {}  # (vlan, src) -> 最后学习逻辑口
    blocked = {}  # (入端口, vlan) -> 封锁截止时刻

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, sim_links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    def member_available(name, t, vlan):
        """成员可用：动态 up、端口 up、STP forwarding 且允许该 VLAN。"""
        port = by_name[name]
        if not member_up[name] or not port["up"] or vlan not in port["allowed"]:
            return False
        return port_status(name, t) == (True, "forwarding")

    def suppress(t, port_name, vlan, src, dst, state, learn_port):
        """风暴控制：返回 True 表示本帧被抑制（不学习、不发送）。"""
        if (port_name, vlan) in blocked:  # 封锁帧不检测
            return True
        if state not in ("learning", "forwarding"):
            return False
        is_group = int(dst[:2], 16) & 1
        if dst == BROADCAST_MAC:
            category = "broadcast"
        elif is_group:
            category = "multicast"
        else:
            category = None if fdb.get((vlan, dst)) else "unknown"
        if category is not None:
            queue = rate_queues.get((port_name, vlan, category))
            if queue is None:
                queue = deque(maxlen=limits[category])
                rate_queues[(port_name, vlan, category)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            if len(queue) >= limits[category]:  # 余量已达上限：丢弃
                return True
        prev = last_learn.get((vlan, src))
        if prev is not None and prev != learn_port:  # 学习端口迁移
            queue = move_queues.get((vlan, src))
            if queue is None:
                queue = deque(maxlen=move_limit)
                move_queues[(vlan, src)] = queue
            while queue and t - queue[0] >= window:
                queue.popleft()
            queue.append(t)
            if len(queue) >= move_limit:  # 迁移数达上限：封锁入端口/VLAN 并丢弃
                blocked[(port_name, vlan)] = t + hold
                return True
        if category is not None:  # 速率名额仅在帧实际放行时占用
            rate_queues[(port_name, vlan, category)].append(t)
        fdb[(vlan, src)] = [learn_port, t]
        last_learn[(vlan, src)] = learn_port
        return False

    U = sum(1 for link in sim_links if link["up"])
    work = B + L + 2 * U  # 初始收敛
    if work > limit:
        raise LagWorkLimit
    converge(0)
    for item in events:
        t = item[1]
        # 老化与解封前取 K、H、Q
        K = len(fdb)
        H = len(blocked)
        Q = sum(len(queue) for queue in rate_queues.values()) + sum(
            len(queue) for queue in move_queues.values()
        )
        kind = item[0]
        if kind == "link":
            up = item[3]
            changed = by_id[item[2]]["up"] != up
            if changed:  # 先应用 up 再计费
                U += 1 if up else -1
                work += K + H + Q + B + L + 2 * U + 2 * P + 1
            else:
                work += K + H + Q + 1
        else:
            # 帧计 P+M，成员事件不计 P、M
            work += K + H + Q + 1 + (0 if kind == "member" else P + M)
        if work > limit:
            raise LagWorkLimit
        # 以下按既有规则处理并更新预演状态
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        for key in [k for k, until in blocked.items() if t >= until]:
            del blocked[key]
        if kind == "link":
            if changed:  # 幂等链路事件不重算拓扑
                old_forwarding = forwarding_ports(t)
                by_id[item[2]]["up"] = item[3]
                converge(t)
                for name in old_forwarding - forwarding_ports(t):
                    for key in [k for k, (p, _) in fdb.items() if p == name]:
                        del fdb[key]
            continue
        if kind == "member":
            member_up[item[2]] = item[3]  # 幂等无作用；可用性变化不清 FDB
            continue
        _, _, port_name, src, dst, tag = item
        if tag is None:
            vlan = by_name[port_name]["pvid"]
            rejected = False
        else:
            vlan = tag
            ingress = by_name[port_name]
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # VLAN 准入拒绝：不学习
            continue
        ingress_lag = lag_of.get(port_name)
        if ingress_lag is not None:
            usable = member_available(port_name, t, vlan)
            state = "forwarding" if usable else None
        else:
            usable = True
            _, state = port_status(port_name, t)
        if usable:  # 不可用成员入帧丢弃且不学习
            learn_port = ingress_lag["name"] if ingress_lag else port_name
            suppress(t, port_name, vlan, src, dst, state, learn_port)


