            bridge,
            ports,
            age,
            storm,
            lags,
            identity,
        ) = validate_lacp_config(config)
        link_ids = {link["id"] for link in links}
        events = validate_lacp_events(data, ports, link_ids, lags)
        # 全量语义校验后无副作用预演；超限不正式仿真
        lacp_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            identity,
            events,
            max_lacp_work,
        )
        result = forward_lacp(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            identity,
            events,
        )
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except LacpWorkLimit:
        _fail("lacp_work_limit")
        return 5
    payload = _result_bytes(result)
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0

